import{_ as r,a0 as u,w as p,s as i,ao as l,I as a,x as e,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在Ubuntu13.10中安裝最新版的NVIDIA 331.20驅動 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu13.10中安裝最新版的NVIDIA 331.20驅動 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu13.10中安裝最新版的NVIDIA 331.20驅動 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu13.10中安裝最新版的NVIDIA 331.20驅動 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/How to Install the Latest NVIDIA 331.20 Driver in Ubuntu 13.10","title":"如何在Ubuntu13.10中安裝最新版的NVIDIA 331.20驅動","tag":"201311","desc":""},"relativePath":"201311/How to Install the Latest NVIDIA 331.20 Driver in Ubuntu 13.10.md","filePath":"[post].md"}'),d={name:"201311/How to Install the Latest NVIDIA 331.20 Driver in Ubuntu 13.10.md"};function I(D,t,m,A,N,V){const n=u("Link");return p(),i("div",null,[t[11]||(t[11]=l(`<h1 id="如何在ubuntu13-10中安裝最新版的nvidia-331-20驅動" tabindex="-1">如何在Ubuntu13.10中安裝最新版的NVIDIA 331.20驅動 <a class="header-anchor" href="#如何在ubuntu13-10中安裝最新版的nvidia-331-20驅動" aria-label="Permalink to “如何在Ubuntu13.10中安裝最新版的NVIDIA 331.20驅動”">​</a></h1><p><strong>有時候安裝新版本的NVIDIA驅動會遇到一些麻煩，尤其是當你不習慣Linux系統中的運作方式時。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-the-Latest-NVIDIA-331-20-Drivers-in-Ubuntu-13-10-399182-2.jpg" alt=""></p><p>這時候，這篇教程就能起到作用了，它能幫助普通用户從最新版的NVIDIA驅動331.20中獲益。</p><p>在Ubuntu系統中有兩種方法安裝NVIDIA驅動，一種是簡單方法，另一種是困難方法。簡單方法也是最為直截了當的，但是需要你能夠連接網絡。這種方法也會把你帶入PPA的美妙世界中去。</p><p>Ubuntu 13.10像它的前輩們一樣，有一個很大的軟件倉庫可供使用，但是Canonical的開發者們由於種種考慮並不上傳最新版的驅動。最重要的是他們不會冒險去上傳一款未被證明其穩定性的軟件。</p><p>幸運的是，我們有PPA可供使用，PPA中有最新版的驅動程序可供使用，而且裏面的驅動會在官方放出新驅動一兩天後就添加進去。只需在終端中敲入一下命令即可（當然你需要擁有root權限）：</p><pre><code>sudo add-apt-repository ppa:xorg-edgers/ppa
sudo apt-get update
sudo apt-get install nvidia-331
</code></pre><p>假如你已經安裝了一箇舊版本的驅動，你需要用<strong>sudo apt-get dist-upgrade</strong>命令替換上面命令中的最後一條命令。</p><p>完成這些步驟之後重啓你的電腦，新驅動就安裝好了。在下一次NVIDIA更新驅動時，你只需更新系統就可以，無需添加PPA。</p><p>第二種方法有點複雜，但是你可以不用聯網（你需要先把驅動下載下來，在安裝的時候不再需要聯網）。我們將使用64位版本的驅動最為例子講解。</p><p>你必須按Ctrl+Alt+F1組合鍵進入真正的終端（譯註：原文中為虛擬終端，但實際上按這個組合鍵進入的是真正的終端），然後使用用户名和密碼登錄。接下倆，你需要用cd命令進入你放置驅動的位置（例如Downloads目錄）然後輸入以下命令：</p><pre><code>sudo service lightdm stop 
sudo chmod a+x NVIDIA-Linux-x86_64-331.20.run
sudo ./NVIDIA-Linux-x86_64-331.20.run
sudo reboot
</code></pre><p>這樣就搞定了。無論你選擇使用什麼方法，享受最新版的NVIDIA驅動吧。</p><hr>`,15)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://news.softpedia.com/news/How-to-Install-the-Latest-NVIDIA-331-20-Drivers-in-Ubuntu-13-10-399182.shtml"},{default:s(()=>[...t[0]||(t[0]=[e("http://news.softpedia.com/news/How-to-Install-the-Latest-NVIDIA-331-20-Drivers-in-Ubuntu-13-10-399182.shtml",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("譯者：",-1)),o(n,{href:"https://github.com/Linux-pdz"},{default:s(()=>[...t[2]||(t[2]=[e("Linux-pdz",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),o(n,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const g=r(d,[["render",I]]);export{T as __pageData,g as default};
